# ---------------- 写盘与自验 ----------------
ids = [p["case_id"] for p in P]
assert len(P) == 20, f"本批应为 20 例，实 {len(P)}"
assert len(set(ids)) == 20, "case_id 有重复"
written = 0
for p in P:
    fp = os.path.join(OUT, p["case_id"] + ".json")
    with open(fp, "w", encoding="utf-8") as f:
        json.dump(p, f, ensure_ascii=False, indent=1)
    written += 1
assert written == 20, f"写出 {written} != 20"
# 回读自验
cnt = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for p in P:
    fp = os.path.join(OUT, p["case_id"] + ".json")
    with open(fp, encoding="utf-8") as f:
        q = json.load(f)
    for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
        assert k in q, f"{p['case_id']} 缺字段 {k}"
    assert q["case_id"] == os.path.splitext(os.path.basename(fp))[0], f"{p['case_id']} 与文件名不对位"
    assert isinstance(q["confidence"], (int, float)) and 0 <= q["confidence"] <= 1
    for b in ("changed_main", "reserve_used", "disputed"):
        assert isinstance(q["trigger"][b], bool)
        if q["trigger"][b]:
            cnt[b] += 1
    assert isinstance(q["trigger"]["reason"], str)
print(f"OK files={written} trigger_counts={cnt} ids={ids}")
